#!/usr/bin/env python3
import csv
import json
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path

ROOT = Path('/root')


def load_json(name):
    with (ROOT / name).open() as f:
        return json.load(f)


def load_csv(name):
    with (ROOT / name).open(newline='') as f:
        return list(csv.DictReader(f))


def parse_bool(value):
    if isinstance(value, bool):
        return value
    if value is None:
        return False
    return str(value).strip().lower() == 'true'


def money(value):
    return Decimal(str(value)).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)


class MoneyEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, Decimal):
            return f"{obj:.2f}"
        return super().default(obj)


def main():
    manifest = load_json('assay_manifest.json')
    carrier_rows = load_csv('carrier_cost.csv')
    billing_rows = load_csv('billing.csv')
    override_rows = load_csv('lab_overrides.csv')
    template = load_json('report_template.json')

    carrier_costs = {
        row['carrier_type']: Decimal(str(row['carrier_cost_usd']))
        for row in carrier_rows
    }

    approved_overrides = {}
    for row in override_rows:
        if row.get('status') != 'approved':
            continue
        assay_id = row['assay_id']
        revision = int(row['revision'])
        if assay_id not in approved_overrides or revision > approved_overrides[assay_id]['revision']:
            approved_overrides[assay_id] = {
                'revision': revision,
                'active_labs': int(row['active_labs']),
            }

    all_assays = []
    for region in manifest.get('regions', []):
        for assay in region.get('assays', []):
            if parse_bool(assay.get('in_scope')):
                item = dict(assay)
                item['region'] = region.get('region')
                all_assays.append(item)

    active_billing = [row for row in billing_rows if parse_bool(row.get('is_active'))]

    assay_results = []
    total_small = Decimal('0.00')
    total_bulk = Decimal('0.00')
    total_diff = Decimal('0.00')

    for assay in sorted(all_assays, key=lambda a: a['assay_id']):
        aliases = assay.get('aliases') or []
        labels = {assay['assay_name'], *aliases}
        matches = [row for row in active_billing if row.get('assay_label') in labels]
        if not matches:
            raise ValueError(f"No active billing row found for {assay['assay_id']}")
        billing = max(matches, key=lambda row: row.get('effective_month', ''))
        payment = Decimal(str(billing['payment_per_run_per_lab_usd']))

        override = approved_overrides.get(assay['assay_id'])
        active_labs = override['active_labs'] if override else int(assay['default_active_labs'])

        carrier_cost = carrier_costs[assay['carrier_type']]
        reagent_price = Decimal(str(assay['reagent_price_per_1000_tests_usd']))
        tests_small = Decimal(str(assay['tests_per_lab_per_run_small']))
        tests_bulk = Decimal(str(assay['tests_per_lab_per_run_bulk']))
        labs = Decimal(active_labs)

        def calc(runs_per_year, tests_per_lab_per_run):
            runs = Decimal(runs_per_year)
            annual_revenue = payment * labs * runs
            annual_reagent_cost = reagent_price * labs * tests_per_lab_per_run * runs / Decimal('1000')
            annual_carrier_cost = carrier_cost * labs * runs
            annual_margin = annual_revenue - annual_reagent_cost - annual_carrier_cost
            return {
                'annual_revenue': annual_revenue,
                'annual_reagent_cost': annual_reagent_cost,
                'annual_carrier_cost': annual_carrier_cost,
                'annual_margin': annual_margin,
            }

        small = calc(24, tests_small)
        bulk = calc(12, tests_bulk)
        diff = bulk['annual_margin'] - small['annual_margin']

        total_small += small['annual_margin']
        total_bulk += bulk['annual_margin']
        total_diff += diff

        assay_results.append({
            'assay_id': assay['assay_id'],
            'assay_name': assay['assay_name'],
            'active_labs': active_labs,
            'billing_label': billing['assay_label'],
            'billing_effective_month': billing['effective_month'],
            'payment_per_run_per_lab_usd': money(payment),
            'carrier_type': assay['carrier_type'],
            'carrier_cost_usd': money(carrier_cost),
            'small_kit': {
                'runs_per_year': 24,
                'annual_revenue_small_kit_usd': money(small['annual_revenue']),
                'annual_reagent_cost_small_kit_usd': money(small['annual_reagent_cost']),
                'annual_carrier_cost_small_kit_usd': money(small['annual_carrier_cost']),
                'annual_margin_small_kit_usd': money(small['annual_margin']),
            },
            'bulk_kit': {
                'runs_per_year': 12,
                'annual_revenue_bulk_kit_usd': money(bulk['annual_revenue']),
                'annual_reagent_cost_bulk_kit_usd': money(bulk['annual_reagent_cost']),
                'annual_carrier_cost_bulk_kit_usd': money(bulk['annual_carrier_cost']),
                'annual_margin_bulk_kit_usd': money(bulk['annual_margin']),
            },
            'annual_margin_difference_bulk_minus_small_usd': money(diff),
        })

    total_small = money(total_small)
    total_bulk = money(total_bulk)
    total_diff = money(total_diff)
    absolute_diff = money(abs(total_diff))

    decision = 'adopt_bulk_kit' if absolute_diff < Decimal('7000.00') else 'keep_small_kit'
    justification = (
        f"Absolute annual margin difference is ${absolute_diff:.2f}, below the $7000.00 threshold."
        if decision == 'adopt_bulk_kit'
        else f"Absolute annual margin difference is ${absolute_diff:.2f}, at or above the $7000.00 threshold."
    )

    report = {
        'metadata': template['metadata'],
        'analysis': {
            'assumptions': {
                'lab_override_rule': 'Use the highest revision approved lab override for each assay_id; otherwise use default_active_labs from the manifest.',
                'billing_rule': 'Use active billing rows matching assay_name or aliases and keep the row with the latest effective_month.',
                'carrier_cost_rule': 'Carrier cost is applied per active lab per run.',
                'currency_rule': 'All USD currency values are rounded to 2 decimal places.',
            },
            'assays': assay_results,
            'totals': {
                'total_annual_margin_small_kit_usd': total_small,
                'total_annual_margin_bulk_kit_usd': total_bulk,
                'total_annual_margin_difference_bulk_minus_small_usd': total_diff,
                'absolute_total_margin_difference_usd': absolute_diff,
            },
            'recommendation': {
                'decision': decision,
                'justification': justification,
            },
        },
    }

    with (ROOT / 'reagent_policy_report.json').open('w') as f:
        json.dump(report, f, indent=2, cls=MoneyEncoder)
        f.write('\n')

    summary_lines = [
        '# Harbor ReagentKit Bulk Policy Summary',
        f"Total small-kit annual margin (USD): ${total_small:.2f}",
        f"Total bulk-kit annual margin (USD): ${total_bulk:.2f}",
        f"Absolute total margin difference (USD): ${absolute_diff:.2f}",
        f"Decision: {decision}",
        justification,
    ]
    with (ROOT / 'reagent_policy_summary.md').open('w') as f:
        f.write('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()

